import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"内部机制：看门狗子系统","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/watchdog.md","filePath":"zh/internals/watchdog.md"}'),n={name:"zh/internals/watchdog.md"};function l(r,a,c,d,i,p){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="内部机制-看门狗子系统" tabindex="-1">内部机制：看门狗子系统 <a class="header-anchor" href="#内部机制-看门狗子系统" aria-label="Permalink to &quot;内部机制：看门狗子系统&quot;">​</a></h1><p><code>kernel/core/core_watchdog.{c,h}</code> - 两个看门狗世界，一个头文件。</p><h2 id="策略看门狗-受监控的槽位" tabindex="-1">策略看门狗（受监控的槽位） <a class="header-anchor" href="#策略看门狗-受监控的槽位" aria-label="Permalink to &quot;策略看门狗（受监控的槽位）&quot;">​</a></h2><p>任务注册一个带超时的槽位：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>slot = watchdog_register(&quot;mydaemon&quot;, 5000, policy);</span></span>
<span class="line"><span>watchdog_start(slot);</span></span>
<span class="line"><span>... watchdog_feed(slot);   /* at least every 5 s */</span></span></code></pre></div><p>超时触发 -&gt; 任务被终止，原因记录到内核日志中（E2E 中的 <code>test log ERROR</code>），内核继续运行。这是&quot;我的后台任务可能挂起&quot;场景的正确工具。</p><h2 id="硬件看门狗" tabindex="-1">硬件看门狗 <a class="header-anchor" href="#硬件看门狗" aria-label="Permalink to &quot;硬件看门狗&quot;">​</a></h2><ul><li><strong>Intel TCO</strong>（LPC）：PMBASE 从芯片组发现，TCOBASE 派生，定时器启动；过期会硬复位机器。在 QEMU q35 上可用 - E2E S12 打印发现行，启动，饥饿，并断言第二次真实启动。</li><li><strong>ACPI WDAT</strong>：表的条目编程硬件；相同的通过重启验证周期（E2E S13）。</li></ul><p><code>watchdog</code> 展示了两个世界：硬件支持 + 槽位表 + 策略测试。</p><h2 id="门禁此功能的-e2e-场景" tabindex="-1">门禁此功能的 E2E 场景 <a class="header-anchor" href="#门禁此功能的-e2e-场景" aria-label="Permalink to &quot;门禁此功能的 E2E 场景&quot;">​</a></h2><p>S7（状态/槽位）、S8（策略终止 + 日志）、S12（TCO 真实复位 + 第二次启动）、S13（WDAT 真实复位 + 第二次启动）。<code>tools/wp12_watchdog_logging_e2e.py</code> 中共有十四个场景 - 发布时全部必须通过。</p>`,11)])])}const g=e(n,[["render",l]]);export{_ as __pageData,g as default};
